 private final CurrentUserProvider users;private final JdbcTemplate db;private final ObjectMapper json;
 private final MoneyService money;private final MoneyProductService product;private final MoneyWebService web;
 private final MoneyMeaningService meaning;private final MoneyClassificationService classification;
 private final MoneyReviewService review;private final MoneyReviewBatchService batches;private final MoneyAiService ai;
 private final MoneyUnifiedBookkeepingService unified;private final MoneyFinancialService financial;
 private final MoneyProcessingReadService processing;private final MoneyReconciliationReadService reconciliation;
