 private MoneyProductService.Category category(UUID id){return product.categories().stream().filter(c->c.id().equals(id)).findFirst().orElseThrow(()->new ResourceNotFoundException("Category not found"));}
 private Map<String,Object> result(Object value){return Map.of("persisted",safe(value),"willChangeFinancialFacts",false);}
 public Object write(String action,Object input){require(WRITE.contains(action),"지원하지 않는 명령입니다.");return switch(action){
  case "category-color" -> {var v=(ColorCommand)input;yield command(v.requestId(),action,v,()->result(product.colorCategory(needed(v.categoryId()),new MoneyCategories.Color(v.color(),v.expectedColor(),v.expectedVersion()))));}
  case "create-category" -> {var v=(CategoryCreate)input;yield command(v.requestId(),action,v,()->result(product.saveCategory(null,new MoneyProductService.CategoryInput(v.name(),v.color(),false,null,needed(v.kind()),v.emoji(),null,v.parentId(),false,v.iconType(),v.iconValue()))));}
  case "category-metadata" -> {var v=(CategoryMetadata)input;yield command(v.requestId(),action,v,()->{var old=category(needed(v.categoryId()));return result(product.saveCategory(old.id(),new MoneyProductService.CategoryInput(needed(v.name()),old.color(),old.archived(),v.expectedVersion(),old.kind(),v.emoji(),old.sortOrder(),old.parentId(),false,v.iconType(),v.iconValue())));});}
  case "category-order" -> {var v=(CategoryOrder)input;yield command(v.requestId(),action,v,()->{require(v.items()!=null&&!v.items().isEmpty()&&v.items().size()<=100,"1–100개 형제 분류가 필요합니다.");var versions=new LinkedHashMap<UUID,Long>();v.items().forEach(i->versions.put(needed(i.id()),needed(i.expectedVersion())));return result(product.orderCategories(new MoneyCategories.Order(v.items().stream().map(Sibling::id).toList(),versions)));});}
  case "bookkeeping-category","bulk-classify" -> {var v=(Classify)input;require(v.items()!=null&&(!action.equals("bookkeeping-category")||v.items().size()==1),"단일 항목을 선택하세요.");yield command(v.requestId(),action,v,()->classify(v,!action.equals("bookkeeping-category")));}
  case "bookkeeping-meaning" -> {var v=(Meaning)input;yield command(v.requestId(),action,v,()->{needed(v.id());require(v.fields()!=null&&!v.fields().isEmpty()&&Set.of("title","memo").containsAll(v.fields()),"제목·메모만 수정할 수 있습니다.");var state=classification.state(v.id());MoneyMeaningService.version(n(state.get("version")),v.classificationVersion());var patch=new LinkedHashMap<String,Object>();for(String field:v.fields())patch.put(field,field.equals("title")?v.title():v.memo());return classification.edit(new MoneyClassificationService.Edit(child(v.requestId(),"meaning"),v.id(),v.transactionVersion(),v.overrideVersion(),v.projectionVersion(),patch,List.of()));});}
  default -> throw new InvalidRequestException("지원하지 않는 명령입니다.");
 };}
 private Map<String,Object> effectiveOutcome(Map<String,Object> value){var out=new LinkedHashMap<String,Object>(value);if("APPLIED".equals(out.get("status"))&&out.get("result") instanceof Map<?,?> r&&r.get("status") instanceof String status&&Set.of("APPLIED","NOT_APPLIED","PARTIAL","UNKNOWN").contains(status))out.put("status",status);return out;}
 private Object command(UUID request,String action,Object input,java.util.function.Supplier<Map<String,Object>> operation){return effectiveOutcome(commands.execute(owner(),needed(request),"ORBIT_"+action,input,()->{var before=Instant.now();var r=operation.get();UUID audit=UUID.randomUUID();db.update("insert into money_meaning_audit(id,user_id,subject_id,action,previous_value,next_value) values(?,?,?,?,cast(? as jsonb),cast(? as jsonb))",audit,owner(),request,"ORBIT_COMMAND",json.writeValueAsString(Map.of("action",action,"requestId",request,"actor",actor())),json.writeValueAsString(safe(r)));var receipt=new LinkedHashMap<String,Object>(r);receipt.put("requestId",request);receipt.put("action",action);receipt.put("auditEventIds",List.of(audit));receipt.put("policyVersion","orbit-money-v1");receipt.put("asOf",before);return receipt;}));}
 private Object actor(){var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(a instanceof org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken j)return Map.of("clientId",Objects.toString(j.getTokenAttributes().get("client_id"),"POS_WEB"),"subject",commands.fingerprint(j.getName()).substring(0,16));return Map.of("clientId","SYNTHETIC_LOCAL");}
 private Map<String,Object> classify(Classify v,boolean bulk){require(v.items()!=null&&!v.items().isEmpty()&&v.items().size()<=50&&v.items().stream().map(ClassifyItem::id).distinct().count()==v.items().size(),"서로 다른 1–50개 거래를 선택하세요.");var applied=new ArrayList<Object>();var excluded=new ArrayList<Object>();for(var i:v.items()){
   var book=web.bookkeepingRow(needed(i.id()));var state=classification.state(i.id());MoneyMeaningService.version(n(state.get("version")),i.classificationVersion());require("CONFIRMED".equals(money.transaction(i.id()).meaningState()),"미확정 금융 의미를 먼저 확인하세요.");
   boolean protect=Boolean.TRUE.equals(state.get("directProtected"))||Boolean.TRUE.equals(book.get("directProtected"));if(protect&&(bulk||!Boolean.TRUE.equals(i.replaceProtected()))){excluded.add(Map.of("id",i.id(),"reason","DIRECT_PROTECTED"));continue;}
   Map<String,Object> change;if(i.categoryId()==null){var patch=new LinkedHashMap<String,Object>();patch.put("categoryId",null);change=classification.edit(new MoneyClassificationService.Edit(child(v.requestId(),i.id().toString()),i.id(),i.transactionVersion(),i.overrideVersion(),i.projectionVersion(),patch,List.of()));}else change=classification.classify(new MoneyClassificationService.Bundle(child(v.requestId(),i.id().toString()),List.of(new MoneyClassificationService.Item(i.id(),i.transactionVersion(),i.overrideVersion(),i.projectionVersion(),i.classificationVersion(),i.categoryId(),true,true))));
   if("APPLIED".equals(change.get("status")))applied.add(Map.of("id",i.id(),"outcome",change));else excluded.add(Map.of("id",i.id(),"reason","CANONICAL_COMMAND_NOT_APPLIED","outcome",change));
  }return Map.of("items",applied,"excluded",excluded,"status",excluded.isEmpty()?"APPLIED":applied.isEmpty()?"NOT_APPLIED":"PARTIAL","willChangeFinancialFacts",false);}
 private static List<String> palette(){return List.of("#5b8def","#2563eb","#57abc3","#45ae99","#0f766e","#84a64d","#e1a34a","#d97706","#e9788d","#D86F72","#be4563","#9771d7","#6d4fb3","#718096","#475569");}
 private double contrast(String color){require(color!=null&&color.matches("#[0-9a-fA-F]{6}"),"#RRGGBB 색상이 필요합니다.");double l=0;double[] w={.2126,.7152,.0722};for(int i=0;i<3;i++){double c=Integer.parseInt(color.substring(1+i*2,3+i*2),16)/255.0;l+=w[i]*(c<=.04045?c/12.92:Math.pow((c+.055)/1.055,2.4));}return 1.05/(l+.05);}
 public Object preview(String action,Object payload){require(PLAN.contains(action),"지원하지 않는 미리보기입니다.");needed(payload);
  // Run canonical financial validation in a completely rolled-back transaction BEFORE taking the preview-storage lock.
  Object financialProposal=action.equals("financial-correction")?dry.execute(status->{try{lock();var before=evidence(action,payload);var v=(Financial)payload;validateFinancial(v);var validated=unified.edit(v.id(),financialEdit(v,UUID.randomUUID()));require("APPLIED".equals(validated.get("status")),"NOT_SUPPORTED: 금융 명령의 안전 전제조건을 충족하지 않습니다.");return Map.of("dryRun",true,"persistedBusinessChanges",false,"canonicalResult",safe(validated),"proposed",v,"validatedEvidenceFingerprint",commands.fingerprint(before));}finally{status.setRollbackOnly();}}):null;
  // Canonical Review previews commit their own independent transaction and must not wait on an outer owner lock.
  Object reviewProposal=action.equals("review-batch")?proposal(action,payload):null;
  return tx.execute(status->{lock();Object evidence=evidence(action,payload);if(financialProposal instanceof Map<?,?> validated)require(Objects.equals(validated.get("validatedEvidenceFingerprint"),commands.fingerprint(evidence)),"PREVIEW_STALE: 금융 검증 이후 근거가 변경되었습니다.");Object proposal=financialProposal!=null?financialProposal:reviewProposal!=null?reviewProposal:proposal(action,payload);UUID key=UUID.randomUUID();var value=new LinkedHashMap<String,Object>();value.put("previewId",key);value.put("action",action);value.put("payload",payload);value.put("evidenceFingerprint",commands.fingerprint(evidence));value.put("proposal",proposal);value.put("expiresAt",Instant.now().plusSeconds(600).toString());value.put("fingerprint",commands.fingerprint(Arrays.asList(action,payload,evidence)));db.update("insert into money_ai_events(id,user_id,subject_id,kind,payload) values(?,?,?,'ORBIT_CONSOLE_PREVIEW',cast(? as jsonb))",key,owner(),key,json.writeValueAsString(value));var out=new LinkedHashMap<String,Object>(value);out.remove("payload");out.put("confirmationRequired",!action.equals("category-color-plan"));return out;});}
 private Object evidence(String action,Object value){return switch(action){
  case "category-color-plan" -> {var v=(ColorPlan)value;require(v.items()!=null&&!v.items().isEmpty()&&v.items().size()<=50&&v.items().stream().map(Color::categoryId).distinct().count()==v.items().size(),"서로 다른 1–50개 분류가 필요합니다.");yield v.items().stream().map(c->category(needed(c.categoryId()))).toList();}
  case "classification-batch" -> {var v=(Classify)value;require(v.items()!=null&&!v.items().isEmpty()&&v.items().size()<=50&&v.items().stream().map(ClassifyItem::id).distinct().count()==v.items().size(),"서로 다른 1–50개 거래가 필요합니다.");yield v.items().stream().map(i->Map.of("book",web.bookkeepingRow(needed(i.id())),"state",classification.state(i.id()),"fact",unified.row(i.id()))).toList();}
  case "rule-change" -> Arrays.asList(meaning.rules(),product.categories());
  case "rule-history" -> meaning.preview((MoneyMeaningService.HistoryRequest)value);
  case "category-structure" -> {var v=(Structure)value;yield Arrays.asList(product.categoryImpact(needed(v.categoryId())),v.parentId()==null?null:product.categoryImpact(v.parentId()));}
  case "financial-correction" -> {var v=(Financial)value;yield Arrays.asList(unified.row(needed(v.id())),v.otherId()==null?null:unified.row(v.otherId()),v.refundOf()==null?null:unified.row(v.refundOf()),web.loans(),money.accounts(),meaning.rules(),product.categories());}
  case "account-settings" -> money.account(needed(((AccountSettings)value).id()));
  case "undo-classification" -> {var v=(UndoPlan)value;require(v.eventIds()!=null&&!v.eventIds().isEmpty()&&v.eventIds().size()<=50,"1–50개 이력이 필요합니다.");yield classification.undoPreview(v.eventIds());}
  case "review-batch" -> {var v=(ReviewPlan)value;require(v.items()!=null&&!v.items().isEmpty()&&v.items().size()<=50,"1–50개 고정 항목이 필요합니다.");yield v.items().stream().map(i->ai.item(i.id(),i.kind(),false)).toList();}
  default -> throw new InvalidRequestException("지원하지 않는 미리보기입니다.");
 };}
 private Object proposal(String action,Object payload){return switch(action){
  case "category-color-plan" -> ((ColorPlan)payload).items().stream().map(c->{var old=category(c.categoryId());MoneyMeaningService.version(old.version(),c.expectedVersion());require(Objects.equals(old.color(),c.expectedColor()),"색상이 변경되었습니다.");return Map.of("categoryId",old.id(),"before",old.color(),"after",c.color(),"expectedVersion",old.version(),"contrastOnWhite",contrast(c.color()),"lowContrastWarning",contrast(c.color())<3,"noOp",old.color().equals(c.color()));}).toList();
  case "review-batch" -> {var v=(ReviewPlan)payload;yield batches.preview(new MoneyReviewBatchService.Preview("SELECTED",v.items(),null,null,null,null,null,v.action()));}
  case "rule-history" -> meaning.preview((MoneyMeaningService.HistoryRequest)payload);
  case "undo-classification" -> classification.undoPreview(((UndoPlan)payload).eventIds());
  case "financial-correction" -> {var v=(Financial)payload;validateFinancial(v);yield Map.of("proposed",v,"current",safe(financial.detail(v.id())),"policy","GUARDED_CANONICAL_COMMAND; same cash movement, no raw/amount/time rewrite; execution revalidates evidence","financialImpact","Canonical projection recomputed; no additional cash posting");}
  default -> Map.of("exactPlan",payload,"current",safe(evidence(action,payload)),"scope",action.equals("rule-change")?"FUTURE_ONLY":"EXACT_SELECTED_IDS","willChangeFinancialFacts",false);
 };}
 private void validateFinancial(Financial v){require(Set.of("TYPE","CORRECT","LINK_TRANSFER","UNLINK_TRANSFER","UNDO_UNLINK").contains(s(v.action(),"")),"지원하지 않는 금융 명령입니다.");needed(v.expectedVersion());if(v.action().equals("TYPE"))require(Set.of("INCOME","EXPENSE","REFUND","TRANSFER","LOAN_PAYMENT").contains(s(v.type(),"")),"금융 유형을 확인하세요.");if(v.refundOf()!=null)require(v.otherVersion()!=null,"원구매 버전이 필요합니다.");if(v.action().equals("LINK_TRANSFER")){needed(v.otherId());needed(v.otherVersion());MoneyService.text(v.reason(),500,true,"Reason");}if(v.action().equals("CORRECT")){needed(v.accountId());MoneyService.text(v.reason(),500,true,"Reason");}}
 private Class<?> type(String action){return switch(action){case "category-color-plan"->ColorPlan.class;case "classification-batch"->Classify.class;case "rule-change"->RuleChange.class;case "rule-history"->MoneyMeaningService.HistoryRequest.class;case "category-structure"->Structure.class;case "financial-correction"->Financial.class;case "account-settings"->AccountSettings.class;case "undo-classification"->UndoPlan.class;case "review-batch"->ReviewPlan.class;default->throw new InvalidRequestException("Unsupported preview");};}
 public Object execute(String action,Execute input){require(input!=null&&input.previewId()!=null&&input.requestId()!=null&&input.confirmed(),"정확한 미리보기 승인이 필요합니다.");
  // Review executes independent canonical transactions; never wrap its REQUIRES_NEW writes in the owner lock.
  if(action.equals("review-batch")){
   var reserved=commands.execute(owner(),input.requestId(),"ORBIT_REVIEW_BATCH",input,()->{var plan=plan(action,input);var proposal=(Map<?,?>)plan.get("proposal");return Map.of("canonicalPreviewId",proposal.get("previewId"),"actor",actor(),"policyVersion","orbit-money-v1");});
   require("APPLIED".equals(reserved.get("status")),"검토 요청을 시작하지 못했습니다.");var pointer=(Map<?,?>)reserved.get("result");return reviewReceipt(batches.execute(new MoneyReviewBatchService.Execute(id(pointer.get("canonicalPreviewId")),input.requestId())));
  }
  return command(input.requestId(),"execute/"+action,input,()->{var plan=plan(action,input);Object payload=json.convertValue(plan.get("payload"),type(action));require(Objects.equals(plan.get("evidenceFingerprint"),commands.fingerprint(evidence(action,payload))),"PREVIEW_STALE: 다시 미리보기 하세요.");return switch(action){
   case "category-color-plan" -> {var out=new ArrayList<Object>();for(var c:((ColorPlan)payload).items())out.add(product.colorCategory(c.categoryId(),new MoneyCategories.Color(c.color(),c.expectedColor(),c.expectedVersion())));yield Map.of("items",out,"status","APPLIED","atomic",true,"willChangeFinancialFacts",false);}
   case "classification-batch" -> {var v=(Classify)payload;yield classify(new Classify(input.requestId(),v.items()),true);}
   case "rule-change" -> {var v=(RuleChange)payload;yield result(meaning.saveRule(v.ruleId(),needed(v.rule())));}
   case "rule-history" -> {var v=(MoneyMeaningService.HistoryRequest)payload;var p=(Map<?,?>)plan.get("proposal");yield meaning.applyHistory(new MoneyMeaningService.HistoryRequest(v.from(),v.to(),p.get("fingerprint").toString()));}
   case "category-structure" -> {var v=(Structure)payload;var old=category(v.categoryId());if("MOVE".equals(v.action()))yield result(product.moveCategory(old.id(),new MoneyCategories.Move(needed(v.parentId()),v.expectedVersion(),v.expectedParentVersion(),product.categoryImpact(old.id()),true)));require("ARCHIVE".equals(v.action()),"이동·보관만 가능합니다.");yield result(product.saveCategory(old.id(),new MoneyProductService.CategoryInput(old.name(),old.color(),true,v.expectedVersion(),old.kind(),old.emoji(),old.sortOrder(),old.parentId(),true,old.iconType(),old.iconValue())));}
   case "financial-correction" -> {var v=(Financial)payload;validateFinancial(v);yield unified.edit(v.id(),financialEdit(v,child(input.requestId(),"financial")));}
   case "account-settings" -> {var v=(AccountSettings)payload;var old=money.account(v.id());var next=money.updateAccount(old.id(),new MoneyTypes.AccountUpdate(v.expectedVersion(),new MoneyTypes.AccountInput(old.provider(),needed(v.displayName()),old.role(),old.maskedReference(),old.suffix(),v.emoji(),old.imageData(),old.fundingAccountId(),v.includeInAssets()==null?old.includeInAssets():v.includeInAssets(),v.includeInStatistics()==null?old.includeInStatistics():v.includeInStatistics(),old.memo())));yield result(next);}
   case "undo-classification" -> {var v=(UndoPlan)payload;var p=(Map<?,?>)plan.get("proposal");yield classification.undo(new MoneyClassificationService.Undo(child(input.requestId(),"undo"),v.eventIds(),p.get("fingerprint").toString()));}
   default -> throw new InvalidRequestException("지원하지 않는 명령입니다.");
  };});
 }
 private MoneyUnifiedBookkeepingService.Edit financialEdit(Financial v,UUID request){return new MoneyUnifiedBookkeepingService.Edit(request,v.expectedVersion(),v.action(),v.type(),v.otherId(),v.otherVersion(),v.loanId(),v.loanVersion(),v.principal(),v.interest(),v.fee(),v.refundOf(),v.accountId(),null,null,v.reason(),v.undoId());}
 private Map<String,Object> plan(String action,Execute input){require(PLAN.contains(action),"Unsupported preview");var found=db.queryForList("select payload::text from money_ai_events where user_id=? and id=? and kind='ORBIT_CONSOLE_PREVIEW'",owner(),input.previewId());if(found.isEmpty())throw new ResourceNotFoundException("Preview not found");var p=json.readValue(found.getFirst().get("payload").toString(),Map.class);require(action.equals(p.get("action"))&&Objects.equals(input.fingerprint(),p.get("fingerprint")),"미리보기 범위가 다릅니다.");require(Instant.parse(p.get("expiresAt").toString()).isAfter(Instant.now()),"PREVIEW_STALE: 미리보기가 만료되었습니다.");return p;}
